select public._wave13_upsert_formula_tools('saudi-tools',$json$[{"slug":"saudi-vat-inclusive-price-calculator","title_ar":"حاسبة السعر شامل الضريبة السعودية","title_en":"Saudi VAT Inclusive Price Calculator","expression":"net_price * (1 + vat_rate / 100)","fields":[{"key":"net_price","ar":"السعر قبل الضريبة","en":"Net price","min":0,"step":0.01},{"key":"vat_rate","ar":"نسبة ضريبة القيمة المضافة %","en":"VAT rate %","min":0,"step":0.01,"max":100}],"sort_order":33701},{"slug":"saudi-vat-exclusive-price-calculator","title_ar":"حاسبة السعر قبل الضريبة السعودية","title_en":"Saudi VAT Exclusive Price Calculator","expression":"inclusive_price / (1 + vat_rate / 100)","fields":[{"key":"inclusive_price","ar":"السعر شامل الضريبة","en":"VAT-inclusive price","min":0,"step":0.01},{"key":"vat_rate","ar":"نسبة ضريبة القيمة المضافة %","en":"VAT rate %","min":0,"step":0.01,"max":100}],"sort_order":33702},{"slug":"saudi-vat-amount-from-inclusive-calculator","title_ar":"حاسبة مبلغ الضريبة من السعر الشامل","title_en":"Saudi VAT Amount from Inclusive Price Calculator","expression":"inclusive_price - inclusive_price / (1 + vat_rate / 100)","fields":[{"key":"inclusive_price","ar":"السعر شامل الضريبة","en":"VAT-inclusive price","min":0,"step":0.01},{"key":"vat_rate","ar":"نسبة ضريبة القيمة المضافة %","en":"VAT rate %","min":0,"step":0.01,"max":100}],"sort_order":33703},{"slug":"saudi-monthly-salary-to-annual-calculator","title_ar":"حاسبة الراتب السعودي الشهري إلى سنوي","title_en":"Saudi Monthly Salary to Annual Calculator","expression":"monthly_salary * 12","fields":[{"key":"monthly_salary","ar":"الراتب الشهري","en":"Monthly salary","min":0,"step":0.01}],"sort_order":33704},{"slug":"saudi-annual-salary-to-monthly-calculator","title_ar":"حاسبة الراتب السعودي السنوي إلى شهري","title_en":"Saudi Annual Salary to Monthly Calculator","expression":"annual_salary / 12","fields":[{"key":"annual_salary","ar":"الراتب السنوي","en":"Annual salary","min":0,"step":0.01}],"sort_order":33705},{"slug":"saudi-daily-wage-from-monthly-calculator","title_ar":"حاسبة الأجر اليومي من الراتب الشهري","title_en":"Saudi Daily Wage from Monthly Salary Calculator","expression":"monthly_salary / working_days","fields":[{"key":"monthly_salary","ar":"الراتب الشهري","en":"Monthly salary","min":0,"step":0.01},{"key":"working_days","ar":"أيام العمل في الشهر","en":"Working days","min":1e-06,"step":0.01}],"sort_order":33706},{"slug":"saudi-hourly-wage-from-monthly-calculator","title_ar":"حاسبة الأجر بالساعة من الراتب الشهري","title_en":"Saudi Hourly Wage from Monthly Salary Calculator","expression":"monthly_salary / monthly_work_hours","fields":[{"key":"monthly_salary","ar":"الراتب الشهري","en":"Monthly salary","min":0,"step":0.01},{"key":"monthly_work_hours","ar":"ساعات العمل الشهرية","en":"Monthly work hours","min":1e-06,"step":0.01}],"sort_order":33707},{"slug":"saudi-rent-monthly-equivalent-calculator","title_ar":"حاسبة المكافئ الشهري للإيجار","title_en":"Saudi Rent Monthly Equivalent Calculator","expression":"annual_rent / 12","fields":[{"key":"annual_rent","ar":"الإيجار السنوي","en":"Annual rent","min":0,"step":0.01}],"sort_order":33708},{"slug":"saudi-installment-income-ratio-calculator","title_ar":"حاسبة نسبة الأقساط إلى الدخل","title_en":"Saudi Installment to Income Ratio Calculator","expression":"monthly_installments / monthly_income * 100","fields":[{"key":"monthly_installments","ar":"الأقساط الشهرية","en":"Monthly installments","min":0,"step":0.01},{"key":"monthly_income","ar":"الدخل الشهري","en":"Monthly income","min":1e-06,"step":0.01}],"sort_order":33709},{"slug":"saudi-budget-surplus-calculator","title_ar":"حاسبة فائض الميزانية الشخصية","title_en":"Saudi Personal Budget Surplus Calculator","expression":"monthly_income - monthly_expenses - monthly_installments","fields":[{"key":"monthly_income","ar":"الدخل الشهري","en":"Monthly income","min":0,"step":0.01},{"key":"monthly_expenses","ar":"المصروفات الشهرية","en":"Monthly expenses","min":0,"step":0.01},{"key":"monthly_installments","ar":"الأقساط الشهرية","en":"Monthly installments","min":0,"step":0.01}],"sort_order":33710}]$json$::jsonb);
select public._wave13_upsert_formula_tools('date-time-tools',$json$[{"slug":"minutes-to-hours-decimal-converter","title_ar":"محول الدقائق إلى ساعات عشرية","title_en":"Minutes to Decimal Hours Converter","expression":"minutes / 60","fields":[{"key":"minutes","ar":"الدقائق","en":"Minutes","min":0,"step":0.01}],"sort_order":33801},{"slug":"hours-to-minutes-calculator","title_ar":"محول الساعات إلى دقائق","title_en":"Hours to Minutes Calculator","expression":"hours * 60","fields":[{"key":"hours","ar":"الساعات","en":"Hours","min":0,"step":0.01}],"sort_order":33802},{"slug":"days-to-hours-total-calculator","title_ar":"حاسبة إجمالي الساعات من الأيام","title_en":"Total Hours from Days Calculator","expression":"days * 24","fields":[{"key":"days","ar":"الأيام","en":"Days","min":0,"step":0.01}],"sort_order":33803},{"slug":"hours-to-days-decimal-converter","title_ar":"محول الساعات إلى أيام عشرية","title_en":"Hours to Decimal Days Converter","expression":"hours / 24","fields":[{"key":"hours","ar":"الساعات","en":"Hours","min":0,"step":0.01}],"sort_order":33804},{"slug":"weeks-to-hours-calculator","title_ar":"حاسبة الساعات من الأسابيع","title_en":"Weeks to Hours Calculator","expression":"weeks * 7 * 24","fields":[{"key":"weeks","ar":"الأسابيع","en":"Weeks","min":0,"step":0.01}],"sort_order":33805},{"slug":"months-to-weeks-estimate-calculator","title_ar":"حاسبة تقدير الأسابيع من الأشهر","title_en":"Months to Weeks Estimate Calculator","expression":"months * 4.345","fields":[{"key":"months","ar":"الأشهر","en":"Months","min":0,"step":0.01}],"sort_order":33806},{"slug":"years-to-months-total-calculator","title_ar":"حاسبة إجمالي الأشهر من السنوات","title_en":"Total Months from Years Calculator","expression":"years * 12","fields":[{"key":"years","ar":"السنوات","en":"Years","min":0,"step":0.01}],"sort_order":33807},{"slug":"weekly-workload-hours-calculator","title_ar":"حاسبة ساعات عبء العمل الأسبوعي","title_en":"Weekly Workload Hours Calculator","expression":"work_days * hours_per_day","fields":[{"key":"work_days","ar":"أيام العمل أسبوعيًا","en":"Work days per week","min":0,"step":0.01},{"key":"hours_per_day","ar":"الساعات يوميًا","en":"Hours per day","min":0,"step":0.01}],"sort_order":33808},{"slug":"work-hours-per-month-estimate-calculator","title_ar":"حاسبة تقدير ساعات العمل الشهرية","title_en":"Monthly Work Hours Estimate Calculator","expression":"weekly_hours * 4.345","fields":[{"key":"weekly_hours","ar":"ساعات العمل الأسبوعية","en":"Weekly work hours","min":0,"step":0.01}],"sort_order":33809},{"slug":"days-per-cycle-calculator","title_ar":"حاسبة الأيام لكل دورة","title_en":"Days per Cycle Calculator","expression":"total_days / cycles","fields":[{"key":"total_days","ar":"إجمالي الأيام","en":"Total days","min":0,"step":0.01},{"key":"cycles","ar":"عدد الدورات","en":"Cycles","min":1e-06,"step":0.01}],"sort_order":33810}]$json$::jsonb);
select public._wave13_upsert_formula_tools('math-tools',$json$[{"slug":"sum-of-three-numbers-calculator","title_ar":"حاسبة مجموع ثلاثة أعداد","title_en":"Sum of Three Numbers Calculator","expression":"a + b + c","fields":[{"key":"a","ar":"العدد الأول","en":"First number","min":-1000000000000.0,"step":0.01},{"key":"b","ar":"العدد الثاني","en":"Second number","min":-1000000000000.0,"step":0.01},{"key":"c","ar":"العدد الثالث","en":"Third number","min":-1000000000000.0,"step":0.01}],"sort_order":33901},{"slug":"average-of-three-numbers-calculator","title_ar":"حاسبة متوسط ثلاثة أعداد","title_en":"Average of Three Numbers Calculator","expression":"(a + b + c) / 3","fields":[{"key":"a","ar":"العدد الأول","en":"First number","min":-1000000000000.0,"step":0.01},{"key":"b","ar":"العدد الثاني","en":"Second number","min":-1000000000000.0,"step":0.01},{"key":"c","ar":"العدد الثالث","en":"Third number","min":-1000000000000.0,"step":0.01}],"sort_order":33902},{"slug":"percentage-point-difference-calculator","title_ar":"حاسبة فرق النقاط المئوية","title_en":"Percentage Point Difference Calculator","expression":"new_rate - old_rate","fields":[{"key":"old_rate","ar":"النسبة السابقة","en":"Previous rate","min":-1000000,"step":0.01},{"key":"new_rate","ar":"النسبة الجديدة","en":"New rate","min":-1000000,"step":0.01}],"sort_order":33903},{"slug":"relative-change-calculator","title_ar":"حاسبة التغير النسبي","title_en":"Relative Change Calculator","expression":"(new_value - old_value) / old_value * 100","fields":[{"key":"old_value","ar":"القيمة السابقة","en":"Previous value","min":1e-06,"step":0.01},{"key":"new_value","ar":"القيمة الجديدة","en":"New value","min":-1000000000000.0,"step":0.01}],"sort_order":33904},{"slug":"ratio-simplified-value-calculator","title_ar":"حاسبة قيمة النسبة","title_en":"Ratio Value Calculator","expression":"value_a / value_b","fields":[{"key":"value_a","ar":"القيمة الأولى","en":"Value A","min":-1000000000000.0,"step":0.01},{"key":"value_b","ar":"القيمة الثانية","